parameters.jsCode:
const row = $input.first().json;
if (row.error || !row.plan) {
  return [{ json: { c: row.c ?? 0, plan: row.plan ?? null, status: row.status ?? null, limit: null, overLimit: false, dbError: true } }];
}
const LIMITS = { trial: 3, start: 1, business: 3, network: 5, none: 0 };
const plan = row.plan;
const status = row.status || 'none';
// M-2 (Task 17a): grace трактуется как expired. Count Dialog не считает диалоги при
// status in ('expired','grace'), поэтому в grace бот уже молчит — раздавать при этом
// слоты (и создавать новые платные Wappi-профили) значит расходиться с метрингом.
const limit = (status === 'expired' || status === 'grace') ? 0 : (LIMITS[plan] ?? 0);
const c = Number(row.c) || 0;
return [{ json: { c, plan, status, limit, overLimit: c >= limit, dbError: false } }];
